mapper.select:
SELECT COUNT(*)
FROM (
    SELECT n.USER_ID AS OWNER_ID
      FROM NOTES n
     WHERE #{contentType} = 'NOTE'
       AND n.NOTE_ID = #{contentId}
    UNION ALL
    SELECT p.CREATED_BY AS OWNER_ID
      FROM PHOTO_POSTS p
     WHERE #{contentType} = 'PHOTO'
       AND p.POST_ID = #{contentId}
) x
WHERE x.OWNER_ID = #{userId}

SELECT COUNT(1)
  FROM PHOTO_POSTS p
 WHERE #{contentType} = 'PHOTO'
   AND p.POST_ID = #{contentId}
   AND UPPER(NVL(p.VISIBILITY_TYPE, 'PRIVATE')) IN ('FRIENDS', 'PUBLIC', 'MOYO', 'GLOBAL')
   AND p.CREATED_BY <> #{userId}

mapper.update:
UPDATE CONTENT_SHARES s
   SET s.ACTIVE_YN = 'N',
       s.UPDATED_AT = SYSDATE
 WHERE s.SHARE_ID = #{shareId}
   AND s.OWNER_ID = #{userId}
   AND s.ACTIVE_YN = 'Y'

mapper.select:

  AND (
       (s.TARGET_TYPE = 'USER' AND s.TARGET_ID = #{userId})
    OR (s.TARGET_TYPE = 'WS' AND EXISTS (
           SELECT 1 FROM WORKSPACES wown
            WHERE wown.WS_ID = s.TARGET_ID AND wown.OWNER_ID = #{userId}
       ))
    OR (s.TARGET_TYPE = 'WS' AND EXISTS (
           SELECT 1 FROM WS_MEMBERS wm
            WHERE wm.WS_ID = s.TARGET_ID
              AND wm.USER_ID = #{userId}
              AND UPPER(NVL(wm.WS_ROLE, 'MEMBER')) = 'ADMIN'
       ))
    OR (s.TARGET_TYPE = 'PROJ' AND EXISTS (
           SELECT 1 FROM PROJECTS pr
            WHERE pr.PROJ_ID = s.TARGET_ID AND pr.LEADER_ID = #{userId}
       ))
    OR (s.TARGET_TYPE = 'PROJ' AND EXISTS (
           SELECT 1 FROM PROJ_MEMBERS pm
            WHERE pm.PROJ_ID = s.TARGET_ID
              AND pm.USER_ID = #{userId}
              AND UPPER(NVL(pm.PROJ_ROLE, 'MEMBER')) IN ('ADMIN', 'LEADER', 'OWNER', 'PM')
       ))
  )
ORDER BY CASE NVL(s.SHARE_STATUS, 'ACCEPTED') WHEN 'PENDING' THEN 1 ELSE 2 END,
         s.CREATED_AT DESC, s.SHARE_ID DESC

mapper.delete:
DELETE FROM CONTENT_SHARES
WHERE CONTENT_TYPE = #{contentType}
  AND CONTENT_ID = #{contentId}
